<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import BackendLayout from '../components/BackendLayout.vue'
import ServiceFields from '../components/ServiceFields.vue'
import {backend,queryString} from '../services/backend'
import {loginManager} from '../services/managerSession'
import {loginCustomer} from '../services/customerSession'
import {useApp} from '../stores/app'
import PostcodeSearch from '../components/PostcodeSearch.vue'
const app=useApp()
function previewMobile(managerPreview:boolean){app.setMemberPreview(true);void router.push(managerPreview?'/admin-app/screen-3':'/customer-app/screen-5')}
import type {Field} from '../data/backendResources'
const route=useRoute(),router=useRouter(),manager=computed(()=>route.path.includes('admin-')),kind=computed(()=>route.path.includes('signup')||/^\/customer-app\/screen-[234]$/.test(route.path)||route.meta.auth==='signup'?'signup':route.path.includes('password-reset')?'reset':'login'),base=computed(()=>manager.value?'/api/managers':'/api/customers'),step=ref(1),busy=ref(false),error=ref(''),message=ref(''),values=reactive<Record<string,any>>({}),verified=ref(false)
const signupFields:Field[]=[{key:'loginId',label:'아이디',required:true},{key:'password',label:'비밀번호',required:true},{key:'passwordConfirm',label:'비밀번호 확인',required:true},{key:'name',label:'이름',required:true},{key:'birthDate',label:'생년월일',type:'date',required:true},{key:'phone',label:'휴대전화',required:true},{key:'email',label:'이메일',type:'email'},{key:'emergency',label:'비상 연락처'},{key:'zipcode',label:'우편번호'},{key:'roadAddress',label:'도로명 주소'},{key:'detailAddress',label:'상세 주소'}]
const fields=computed<Field[]>(()=>kind.value==='login'?[{key:'loginId',label:'아이디',required:true},{key:'password',label:'비밀번호',required:true}]:kind.value==='reset'?(step.value===1?[{key:'loginId',label:'아이디',required:true},{key:'phone',label:'휴대전화',required:true}]:step.value===2?[{key:'code',label:'인증번호',required:true}]:[{key:'newPassword',label:'새 비밀번호',required:true},{key:'newPasswordConfirm',label:'새 비밀번호 확인',required:true}]):manager.value?(step.value===1?[{key:'name',label:'이름',required:true},{key:'birthDate',label:'생년월일',type:'date',required:true},{key:'phone',label:'휴대전화',required:true}]:step.value===2?[{key:'code',label:'인증번호',required:true}]:signupFields.slice(0,3)):step.value===1?[{key:'phone',label:'휴대전화',required:true}]:step.value===2?[{key:'code',label:'인증번호',required:true}]:signupFields.filter(field=>field.key!=='phone'))
function authLink(mode:'login'|'signup'|'reset'){const mobile=route.path.includes('-app/');if(mobile){const prefix=manager.value?'/admin-app/':'/customer-app/';return prefix+(mode==='login'?'screen-1':mode==='reset'?'password-reset':manager.value?'signup':'screen-2')}return manager.value?'/admin-'+(mode==='reset'?'password-reset':mode):'/'+(mode==='reset'?'password-reset':mode)}
async function submit(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{
 if(kind.value==='login'){if(manager.value)await loginManager(values.loginId,values.password);else await loginCustomer(values.loginId,values.password);await router.push(manager.value?(route.path.startsWith('/admin-app/')?'/admin-app/screen-3':'/admin-dashboard'):route.path.startsWith('/customer-app/')?'/customer-app/screen-5':'/my-home');return}
 if(kind.value==='reset'){if(step.value===1){await backend(base.value+'/password-reset/request',{method:'POST',body:{loginId:values.loginId,phone:values.phone}});step.value=2;message.value='인증번호를 발송했습니다.'}else if(step.value===2){await backend(base.value+'/password-reset/verify',{method:'POST',body:{code:values.code}});step.value=3}else{if(values.newPassword!==values.newPasswordConfirm)throw new Error('새 비밀번호 확인이 일치하지 않습니다.');await backend(base.value+'/password-reset/confirm',{method:'POST',body:{newPassword:values.newPassword,newPasswordConfirm:values.newPasswordConfirm}});await router.push(authLink('login'))}return}
 if(step.value===1){await backend(base.value+(manager.value?'/signup/employee-check':'/phone-code/send'),{method:'POST',body:manager.value?{name:values.name,birthDate:values.birthDate,phone:values.phone}:{phone:values.phone}});step.value=2;message.value='인증번호를 발송했습니다.'}else if(step.value===2){await backend(base.value+(manager.value?'/signup/phone-code/verify':'/phone-code/verify'),{method:'POST',body:manager.value?{code:values.code}:{phone:values.phone,code:values.code}});verified.value=true;step.value=3}else{if(!verified.value)throw new Error('휴대전화 인증이 필요합니다.');if(values.password!==values.passwordConfirm)throw new Error('비밀번호 확인이 일치하지 않습니다.');const body=manager.value?{loginId:values.loginId,password:values.password,passwordConfirm:values.passwordConfirm}:Object.fromEntries(signupFields.map(field=>[field.key,values[field.key]||null]));await backend(base.value+'/signup',{method:'POST',body});message.value=manager.value?'가입 신청이 접수되었습니다. 승인 후 로그인할 수 있습니다.':'회원가입이 완료되었습니다. 로그인해 주세요.';step.value=4}
 }catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function checkId(){error.value='';try{const result=await backend(base.value+'/check-login-id'+queryString({loginId:values.loginId}));message.value=result.available?'사용 가능한 아이디입니다.':'이미 사용 중인 아이디입니다.'}catch(e){error.value=(e as Error).message}}
async function resend(){busy.value=true;error.value='';try{await backend(base.value+(manager.value?'/signup/phone-code/resend':'/phone-code/send'),{method:'POST',body:manager.value?undefined:{phone:values.phone}});message.value='인증번호를 다시 발송했습니다.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><component :is="manager?BackendLayout:'div'"><section class="service-workspace auth-service"><h1>{{manager?'관리자':'고객'}} {{kind==='login'?'로그인':kind==='signup'?'회원가입':'비밀번호 재설정'}}</h1><p v-if="kind!=='login'&&step<4">{{step}} / 3단계</p><p v-if="error" class="service-error" role="alert">{{error}}</p><p v-if="message" class="service-message" role="status">{{message}}</p><form v-if="step<4" @submit.prevent="submit"><div class="service-form-fields"><label v-for="field in fields" :key="field.key">{{field.label}}<input v-model="values[field.key]" :type="/password/i.test(field.key)?'password':field.type||'text'" :required="field.required" :autocomplete="field.key==='password'?(kind==='login'?'current-password':'new-password'):field.key==='detailAddress'?'address-line2':undefined" :disabled="busy" :maxlength="field.key==='code'?10:100"><PostcodeSearch v-if="field.key==='zipcode'" :disabled="busy" @select="address=>{values.zipcode=address.zipcode;values.roadAddress=address.roadAddress;values.detailAddress=''}"/></label></div><div class="auth-buttons"><button v-if="kind==='signup'&&step===3" type="button" :disabled="busy||!values.loginId" @click="checkId">아이디 중복 확인</button><button v-if="kind==='signup'&&step===2" type="button" :disabled="busy" @click="resend">인증번호 다시 받기</button><button type="submit" :disabled="busy">{{busy?'처리 중…':kind==='login'?'로그인':step===3?(kind==='signup'?'가입 신청':'비밀번호 변경'):'다음'}}</button></div></form><section v-if="kind==='login'&&!app.account" class="auth-preview"><p>로그인 없이 앱 화면을 미리 확인할 수 있습니다.</p><div><button type="button" @click="previewMobile(false)">고객 앱 둘러보기</button><button type="button" @click="previewMobile(true)">관리자 앱 둘러보기</button></div><small>미리보기는 예시 화면이며 실제 계정에 로그인하지 않습니다.</small></section><nav class="auth-links"><RouterLink :to="authLink('login')">로그인</RouterLink><RouterLink :to="authLink('signup')">회원가입</RouterLink><RouterLink :to="authLink('reset')">비밀번호 재설정</RouterLink></nav></section></component></template>
<style scoped>.auth-preview{margin-top:24px;padding-top:16px;border-top:1px solid var(--line)}.auth-preview p{font-size:14px}.auth-preview>div{display:flex;flex-wrap:wrap;gap:10px}.auth-preview small{display:block;margin-top:10px;color:var(--ink-sub,#64748b);font-size:12px}.auth-service{max-width:680px;margin:24px auto;padding:24px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.auth-service h1{font-size:24px;margin:0 0 20px}.auth-buttons,.auth-links{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}.auth-buttons{justify-content:flex-end}.auth-links{font-size:13px}.auth-service button{min-height:44px;padding:10px 16px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:inherit}.auth-service .auth-buttons button[type=submit]{background:#173d62;color:white}@media(max-width:600px){.auth-service{margin:12px 0;padding:20px 16px}}</style>
